package com.sanctuarygames.createtransit.radio;
import com.mojang.serialization.MapCodec;import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;
/** One speaker model mounts to walls or ceiling using the clicked face. */
public final class StationSpeakerBlock extends BaseEntityBlock {
 public static final DirectionProperty FACING=BlockStateProperties.FACING;public static final MapCodec<StationSpeakerBlock> CODEC=com.mojang.serialization.codecs.RecordCodecBuilder.mapCodec(i->i.group(propertiesCodec(),com.mojang.serialization.Codec.STRING.optionalFieldOf("style","box").forGetter(b->b.style)).apply(i,StationSpeakerBlock::new));
 public final String style;public StationSpeakerBlock(Properties p){this(p,"box");}public StationSpeakerBlock(Properties p,String style){super(p);this.style=style;registerDefaultState(defaultBlockState().setValue(FACING,Direction.NORTH));}
 @Override protected MapCodec<? extends BaseEntityBlock> codec(){return CODEC;}
 @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(FACING);}
 @Override public BlockState getStateForPlacement(BlockPlaceContext c){return defaultBlockState().setValue(FACING,c.getClickedFace());}
 @Override protected RenderShape getRenderShape(BlockState s){return RenderShape.MODEL;}
 @Override protected VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){double[] b=switch(style){case "ceiling"->new double[]{2,2,12.9,14,14,16};case "column"->new double[]{5,0,11.9,11,16,16};case "horn"->new double[]{2,2,7,14,14,16};default->new double[]{3,3,11.9,13,13,16};};var shape=box(b[0],b[1],b[2],b[3],b[4],b[5]);var f=s.getValue(FACING);if(f.getAxis().isHorizontal())return com.sanctuarygames.createtransit.elevator.ElevatorPartBlock.turn(shape,f);return f==Direction.DOWN?box(b[0],b[2],16-b[4],b[3],b[5],16-b[1]):box(b[0],16-b[5],b[1],b[3],16-b[2],b[4]);}
 @Override protected ItemInteractionResult useItemOn(net.minecraft.world.item.ItemStack stack,BlockState state,Level level,BlockPos pos,Player player,InteractionHand hand,BlockHitResult hit){if(stack.getItem() instanceof net.minecraft.world.item.DyeItem dye){if(!player.mayBuild())return ItemInteractionResult.FAIL;if(!level.isClientSide&&level.getBlockEntity(pos) instanceof StationSpeakerEntity e){int value=dye.getDyeColor().getId();boolean changed=(player.isShiftKeyDown()?e.secondary:e.primary)!=value;if(player.isShiftKeyDown())e.secondary=value;else e.primary=value;e.setChanged();level.sendBlockUpdated(pos,state,state,3);if(changed&&!player.isCreative())stack.shrink(1);}return ItemInteractionResult.sidedSuccess(level.isClientSide);}return super.useItemOn(stack,state,level,pos,player,hand,hit);}
 @Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new StationSpeakerEntity(p,s);}
 @Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player player,BlockHitResult hit){if(!l.isClientSide&&l.getBlockEntity(p) instanceof StationSpeakerEntity e)e.open(player);return InteractionResult.sidedSuccess(l.isClientSide);}
}
